import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, SRGBColorSpace } = THREE;

  const group = new Group();
  const inner = new Group();
  group.add(inner);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };

  // --- Card plane (textured accent) ---------------------------------------
  const atlas = config.atlas ?? { rect: [0, 0, 512, 320], width: 512, height: 320 };
  const rect = atlas.rect ?? [0, 0, 512, 320];
  const atlasW = atlas.width ?? rect[2];
  const atlasH = atlas.height ?? rect[3];

  const cardGeo = new PlaneGeometry(1.0, 0.62);
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    opacity: 0.95,
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      // Sub-rect onto the atlas sheet — preserve aspect of the region itself.
      const rw = rect[2] / atlasW;
      const rh = rect[3] / atlasH;
      tex.repeat.set(rw, rh);
      tex.offset.set(rect[0] / atlasW, 1 - (rect[1] + rect[3]) / atlasH);
      tex.needsUpdate = true;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0);
  inner.add(card);

  // --- Accent ribbon edge (signal red) -------------------------------------
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.95,
    side: DoubleSide,
  });
  const edgeGeo = new PlaneGeometry(0.035, 0.62);
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(-0.4975, 0, 0.0012);
  inner.add(edge);

  // --- Hairline border for engineered definition ---------------------------
  const borderMat = new MeshBasicNodeMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: 0.55,
    side: DoubleSide,
  });
  const borderGeo = new PlaneGeometry(1.012, 0.632);
  const border = new Mesh(borderGeo, borderMat);
  border.position.set(0, 0, -0.001);
  inner.add(border);

  // --- Label text: "Journal 3" ---------------------------------------------
  const headItem = items.find((i) => i.role === 'headline') ?? items[0];
  let label = null;
  if (headItem && headItem.text != null) {
    label = ctx.fontAtlas.createText(String(headItem.text), {
      fontSize: 39,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 1.4,
    });
    label.position.set(-0.44, -0.045, 0.002);
    inner.add(label);
  }

  // --- Interactions --------------------------------------------------------
  const tag = { y: 0 };
  const baseY = 0;
  const liftY = 0.15;

  function onHover() {
    gsap.to(inner.position, { y: baseY + liftY, duration: 0.6, ease: 'power3.out', overwrite: true });
    gsap.to(edgeMat, { opacity: 1.0, duration: 0.35, ease: 'power2.out', overwrite: true });
    gsap.to(edge.scale, { y: 1.08, duration: 0.4, ease: 'power2.out', overwrite: true });
  }
  function onBlur() {
    gsap.to(inner.position, { y: baseY, duration: 0.5, ease: 'power3.out', overwrite: true });
    gsap.to(edgeMat, { opacity: 0.95, duration: 0.35, ease: 'power2.out', overwrite: true });
    gsap.to(edge.scale, { y: 1.0, duration: 0.4, ease: 'power2.out', overwrite: true });
  }
  function onClick() {
    gsap.timeline({ overwrite: true })
      .to(inner.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
      .to(inner.scale, { x: 1.0, y: 1.0, duration: 0.18, ease: 'power4.out' });
    ctx.emit('navigate', { to: 'hub-journal.select' });
  }

  group.userData.handlers = { hover: onHover, blur: onBlur, click: onClick };

  // --- Cleanup -------------------------------------------------------------
  group.userData.cleanup = () => {
    gsap.killTweensOf(inner.position);
    gsap.killTweensOf(inner.scale);
    gsap.killTweensOf(edge.scale);
    gsap.killTweensOf(edgeMat);
    cardGeo.dispose();
    cardMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
  };

  return group;
}
